mapper.select:
select  from outbound_tasks
where house_id = #{houseId} and operator_id = #{operatorId} and task_id = #{taskId}
for update

mapper.update:
update outbound_tasks set status = 'CANCELLED', revision = revision + 1, update_time = now()
where house_id = #{houseId} and operator_id = #{operatorId} and task_id = #{taskId}
  and status in ('SELECTING', 'WAITING_CONFIRMATION')

update outbound_tasks set status = 'SUBMITTING', request_id = #{requestId}, update_time = now()
where house_id = #{houseId} and operator_id = #{operatorId} and task_id = #{taskId}
  and status = 'WAITING_CONFIRMATION'

update outbound_tasks set status = 'WAITING_CONFIRMATION', update_time = now()
where house_id = #{houseId} and operator_id = #{operatorId} and task_id = #{taskId}
  and request_id = #{requestId} and status = 'SUBMITTING'
